/**
 * Launch ("splash") screens for the installed iPhone/iPad app.
 *
 * Without these, iOS paints a plain white screen between tapping the Home Screen
 * icon and the first frame of the app, which on a dark-mode phone is a bright
 * flash. iOS only uses a startup image when a `<link rel="apple-touch-startup-image">`
 * matches the device's exact CSS size and pixel ratio, so there is one entry per
 * device size, in a light and a dark flavour (matched with prefers-color-scheme).
 *
 * The images themselves are flat app-background colour with the app icon centred,
 * generated by `scripts/generate-splash.cjs` into `public/icons/v2/splash/`. They sit
 * under `/icons/`, which `proxy.ts` already leaves outside the login gate — iOS
 * fetches them before any session exists.
 *
 * Portrait only. An iPad launched in landscape gets iOS's default blank launch,
 * which is what every device got before this existed.
 *
 * Keep this list in step with `SIZES` in scripts/generate-splash.cjs;
 * tests/splash.test.ts fails if an image listed here is missing on disk.
 */

/** [CSS width, CSS height, device pixel ratio] — portrait. */
export const SPLASH_SIZES: ReadonlyArray<readonly [number, number, number]> = [
  // iPhone 16/17 Pro Max
  [440, 956, 3],
  // iPhone 16/17 Pro
  [402, 874, 3],
  // iPhone 14 Pro Max / 15 Plus / 15 Pro Max / 16 Plus
  [430, 932, 3],
  // iPhone 14 Pro / 15 / 15 Pro / 16
  [393, 852, 3],
  // iPhone 12 / 12 Pro / 13 / 13 Pro / 14
  [390, 844, 3],
  // iPhone X / XS / 11 Pro / 12 mini / 13 mini
  [375, 812, 3],
  // iPhone XS Max / 11 Pro Max
  [414, 896, 3],
  // iPhone XR / 11
  [414, 896, 2],
  // iPhone SE (2nd/3rd gen) / 8
  [375, 667, 2],
  // iPad Pro 12.9"
  [1024, 1366, 2],
  // iPad Pro 11"
  [834, 1194, 2],
  // iPad Air 10.9" / iPad 10th gen
  [820, 1180, 2],
  // iPad 10.2"
  [810, 1080, 2],
];

export type SplashScheme = 'light' | 'dark';

/** The ratio is part of the name: 414x896 exists at both 2x and 3x. */
export function splashPath(
  scheme: SplashScheme,
  width: number,
  height: number,
  ratio: number,
): string {
  return `/icons/v2/splash/${scheme}-${width}x${height}@${ratio}x.png`;
}

/** The `startupImage` list Next turns into `<link rel="apple-touch-startup-image">`. */
export function splashStartupImages(): Array<{ url: string; media: string }> {
  return SPLASH_SIZES.flatMap(([width, height, ratio]) => {
    const media =
      `(device-width: ${width}px) and (device-height: ${height}px) ` +
      `and (-webkit-device-pixel-ratio: ${ratio}) and (orientation: portrait)`;

    // Both flavours carry an explicit colour-scheme condition. A bare "light"
    // entry would also match a dark-mode phone, leaving iOS to choose between
    // two matching images — and if it picked the light one, the white flash
    // these exist to remove would come straight back.
    return [
      {
        url: splashPath('light', width, height, ratio),
        media: `${media} and (prefers-color-scheme: light)`,
      },
      {
        url: splashPath('dark', width, height, ratio),
        media: `${media} and (prefers-color-scheme: dark)`,
      },
    ];
  });
}
